def _tool(name: str, argsModel: type[BaseModel]) -> dict:
    return {
        'type': 'function',
        'function': {
            'name': name,
            'description': DESCRIPTIONS[name],
            'parameters': argsModel.model_json_schema(by_alias=True),
        },
    }


TOOL_CALLS = {
    'admin': {
        'addStoreProduct': (AddStoreProductArgs, _addStoreProduct),
        'addStoreProducts': (AddStoreProductsArgs, _addStoreProducts),
        'approveReturn': (ApproveReturnArgs, _approveReturn),
        'cancelStoreOrder': (CancelStoreOrderArgs, _cancelStoreOrder),
        'completeOrder': (CompleteOrderArgs, _completeOrder),
        'createUserStore': (CreateUserStoreArgs, _createUserStore),
        'generateProductPhotos': (GenerateProductPhotosArgs, _generateProductPhotos),
        'getMyStorePolicy': (GetMyStorePolicyArgs, _getMyStorePolicy),
        'getStoreOrders': (GetStoreOrdersArgs, _getStoreOrders),
        'getStoreReturns': (GetStoreReturnsArgs, _getStoreReturns),
        'getUserStore': (GetUserStoreArgs, _getUserStore),
        'listMyStoreProducts': (ListMyStoreProductsArgs, _listMyStoreProducts),
        'listVoices': (ListVoicesArgs, _listVoices),
        'receiveReturn': (ReceiveReturnArgs, _receiveReturn),
        'rejectReturn': (RejectReturnArgs, _rejectReturn),
        'setProductPhoto': (SetProductPhotoArgs, _setProductPhoto),
        'updateMyStorePolicy': (UpdateMyStorePolicyArgs, _updateMyStorePolicy),
        'updateMyStoreTheme': (UpdateMyStoreThemeArgs, _updateMyStoreTheme),
        'updateStoreProduct': (UpdateStoreProductArgs, _updateStoreProduct),
    },
    'customer': {
        'cancelMyOrder': (CancelMyOrderArgs, _cancelMyOrder),
        'cancelMyReturn': (CancelMyReturnArgs, _cancelMyReturn),
        'createOrder': (CreateOrderArgs, _createOrder),
        'getMyOrders': (GetMyOrdersArgs, _getMyOrders),
        'getMyReturns': (GetMyReturnsArgs, _getMyReturns),
        'getStorePolicy': (GetStorePolicyArgs, _getStorePolicy),
        'listStoreProducts': (ListStoreProductsArgs, _listStoreProducts),
        'payOrder': (PayOrderArgs, _payOrder),
        'requestReturn': (RequestReturnArgs, _requestReturn),
    },
    'adminSetup': {
        'createUserStore': (CreateUserStoreArgs, _createUserStore),
        'getUserStore': (GetUserStoreArgs, _getUserStore),
    },
}

TOOLS = {
    toolset: sorted(
        [_tool(name, argsModel) for name, (argsModel, _) in calls.items()]
        + chatForms.formToolSchemas(toolset),
        key=lambda tool: tool['function']['name'])
    for toolset, calls in TOOL_CALLS.items()
}
